'''
new='''  const now = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // Accepting consumes the invitation whoever accepts it. A current member's
  // membership is left exactly as it is; a former member is re-admitted on
  // their existing row, so their history stays attached to it.
  const readmitted = existing !== null && existing.archivedAt !== null;
  const member =
    existing === null
      ? await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
        )
      : readmitted
        ? await memberRepo.reactivateMember(
            invitation.orgId,
            existing.id,
            invitation.role,
            invitation.invitedBy,
            now,
          )
        : existing;

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    now,
  );

  if (existing !== null && !readmitted) return member;

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
